/**
 * GurtAI's CRM: a deterministic, simulated HubSpot-style system with ~22 months of history.
 *
 * History is generated by simulated employees who follow GurtAI's (unwritten) rules, with exceptions and one policy
 * change. Nothing in the API states these rules; they only show up in the history. TRUTH lists them so evals can
 * score what the miner found. The same module serves the REST API locally and on Manufact.
 *
 * Rules the employees follow:
 *   commit      deals closing in the quarter that are Closed Won AND booked, or in Contract Sent; valued at arr;
 *               the Partner Sandbox pipeline never counts. From 2026-10-01 RevOps stops counting Contract Sent.
 *   booked      RevOps ticks `booked` 3–10 days after Closed Won (most won deals; a few unwind and never get it)
 *   owners      new contacts are assigned by the territory of their country; existing contacts keep their owner
 *               (one manual exception in 2026)
 *   dedupe      duplicate companies (www./case variants of a domain) are merged into the oldest one
 */

import { DAY, iso, mulberry32, NOW, START, type Req, type Res } from "./common.js";
import { ErpSystem } from "./erp.js";
import { MailSystem } from "./mail.js";
export { NOW, type Req, type Res };

