// ── generated data ──────────────────────────────────────────────────────────
export type Obj = { id: string; properties: Record<string, string> };
export interface Change { object: "deal" | "contact" | "company"; id: string; property: string; old: string | null; new: string | null; changed_at: string; changed_by: string }
export interface Snapshot { as_of: string; quarter: string; reported_commit_usd: number; deal_ids: string[] }
export interface World { deals: Obj[]; contacts: Obj[]; companies: Obj[]; history: Change[]; snapshots: Snapshot[] }

export const TRUTH = {
  rules: [
    { id: "commit", text: "Commit counts Closed Won deals only when booked = true, plus deals in Contract Sent" },
    { id: "value", text: "Commit is valued at arr, not amount (amount includes one-time services)" },
    { id: "sandbox", text: "The Partner Sandbox pipeline never counts" },
    { id: "territory", text: "New contacts are owned by the territory of their country (EMEA 201, Americas 202, APAC 203)" },
    { id: "keep_owner", text: "Existing contacts keep their owner when they show up again" },
    { id: "dedupe", text: "Companies are the same if their root domain matches (lowercase, no scheme, no www.)" },
  ],
  drift: { rule: "commit", from: "2026-10-01", text: "From October 2026, Contract Sent deals no longer count toward commit" },
};

export function quarterOf(t: number): { label: string; start: number; end: number } {
  const d = new Date(t);
  const q = Math.floor(d.getUTCMonth() / 3);
  const start = Date.UTC(d.getUTCFullYear(), q * 3, 1);
  const end = Date.UTC(d.getUTCFullYear(), q * 3 + 3, 1) - 1;
  return { label: `${d.getUTCFullYear()}-Q${q + 1}`, start, end };
}
export const territoryOf = (country: string) => COUNTRIES[country];
export const rootDomain = (s: string) => s.trim().toLowerCase().replace(/^[a-z]+:\/\//, "").split("/")[0]!.replace(/^www\./, "");

export function generate(seed = 20261031): World {
  const rand = mulberry32(seed);
  const pick = <T>(xs: readonly T[]) => xs[Math.floor(rand() * xs.length)]!;
  const between = (a: number, b: number) => a + Math.floor(rand() * (b - a + 1));
  const history: Change[] = [];
  const log = (object: Change["object"], id: string, property: string, old: string | null, nw: string | null, t: number, by: string) =>
    history.push({ object, id, property, old, new: nw, changed_at: iso(t), changed_by: by });

  // companies (+ duplicates later merged)
  const names = ["Northwind", "Globex", "Initech", "Umbrella", "Soylent", "Hooli", "Kaito", "Vandelay", "Stark", "Wayne", "Cyberdyne", "Tyrell",
    "Wonka", "Acorn", "Aperture", "Black Mesa", "Dunder", "Gekko", "Hanso", "Ingen", "Krusty", "Lacuna", "Massive", "Nakatomi", "Oceanic",
    "Pied Piper", "Quark", "Rekall", "Sirius", "Virtucon", "Weyland", "Xanadu", "Yoyodyne", "Zorg", "Bluth", "Cogswell", "Duff", "Ewing",
    "Frobozz", "Gringotts", "Halcyon", "Iridium", "Jupiter", "Kelso", "Lunar", "Monarch", "Nimbus", "Orbit", "Paragon", "Quantum"];
  const tlds = [".com", ".io", ".ai", ".de", ".co.uk", ".jp", ".com.au", ".sg"];
  const companies: Obj[] = [];
  let cid = 30100;
  for (const n of names) {
    const country = pick(Object.keys(COUNTRIES));
    const domain = n.toLowerCase().replace(/\s+/g, "") + pick(tlds);
    const t = START + between(0, 60) * DAY;
    const id = String(++cid);
    companies.push({ id, properties: { name: n + pick([" Inc", " GmbH", " Ltd", " Labs", ""]), domain, country, createdate: iso(t) } });
    log("company", id, "domain", null, domain, t, "205");
  }
  // 14 duplicates created later with www./case/scheme variants, merged by RevOps within weeks
  const originals = companies.length;
  for (let i = 0; i < 14; i++) {
    const orig = companies[between(0, originals - 1)]!;
    const variant = pick([`www.${orig.properties.domain}`, orig.properties.domain!.toUpperCase(), `https://${orig.properties.domain}/`, `WWW.${orig.properties.domain}`]);
    const t = START + between(90, 600) * DAY;
    const id = String(++cid);
    companies.push({ id, properties: { name: orig.properties.name!, domain: variant, country: orig.properties.country!, createdate: iso(t), merged_into: orig.id } });
    log("company", id, "domain", null, variant, t, "205");
    log("company", id, "merged_into", null, orig.id, t + between(3, 30) * DAY, "204");
  }
  const live = companies.filter((c) => !c.properties.merged_into);

  // contacts: created over time, owner by territory; some reappear at events (owner kept)
  const contacts: Obj[] = [];
  let pid = 40100;
  const events = ["SaaStr Annual 2025", "Dreamforce 2025", "Web Summit 2025", "SaaStr Annual 2026", "Money20/20 2026"];
  const first = ["Ava", "Liam", "Mei", "Rahul", "Sofie", "Jonas", "Kenta", "Olivia", "Hannah", "Grace", "Ethan", "Chloe", "Jack", "Li", "Noah", "Emma", "Lucas", "Maya", "Omar", "Zoe"];
  const last = ["Thompson", "Weber", "Chen", "Iyer", "Larsen", "Mori", "Brooks", "Fischer", "Kim", "Price", "Martin", "Wilson", "Wei", "Smith", "Garcia", "Novak", "Rossi", "Haddad", "Tanaka", "Okafor"];
  for (let i = 0; i < 420; i++) {
    const co = pick(live);
    const country = rand() < 0.8 ? co.properties.country! : pick(Object.keys(COUNTRIES));
    const t = START + between(0, 650) * DAY + between(0, 23) * 3_600_000;
    const fn = pick(first), ln = pick(last);
    const id = String(++pid);
    const source = pick(["EVENT", "EVENT", "INBOUND", "OUTBOUND", "PARTNER", "REFERRAL"]);
    const owner = COUNTRIES[country]!;
    contacts.push({ id, properties: { email: `${fn}.${ln}.${i}@${rootDomain(co.properties.domain!)}`.toLowerCase(), firstname: fn, lastname: ln, country, company_id: co.id,
      lead_source: source, lifecyclestage: "lead", hubspot_owner_id: owner, createdate: iso(t), ...(source === "EVENT" ? { last_event: pick(events.slice(0, 3)) } : {}) } });
    log("contact", id, "hubspot_owner_id", null, owner, t + 60_000, "205");
  }
  // later: a few owners change by hand (vacations, reorgs) so territory is not 100%
  for (let i = 0; i < 6; i++) {
    const c = pick(contacts);
    const to = pick(["201", "202", "203"].filter((o) => o !== c.properties.hubspot_owner_id));
    const t = Date.parse(c.properties.createdate!) + between(20, 200) * DAY;
    if (t > NOW) continue;
    log("contact", c.id, "hubspot_owner_id", c.properties.hubspot_owner_id!, to, t, "204");
    c.properties.hubspot_owner_id = to;
  }
  // existing contacts reappear at 2026 events: last_event changes, owner kept, even when it differs from territory
  const reappear = contacts.filter((c) => Date.parse(c.properties.createdate!) < Date.UTC(2026, 0, 1)).slice(0, 60);
  reappear.forEach((c, i) => {
    const t = Date.UTC(2026, 2 + (i % 6), 10 + (i % 15));
    log("contact", c.id, "last_event", c.properties.last_event ?? null, events[3 + (i % 2)]!, t, "205");
    c.properties.last_event = events[3 + (i % 2)]!;
    if (i === 7) { // the one manual exception: RevOps moved a re-captured contact to its territory owner
      const terr = COUNTRIES[c.properties.country!]!;
      const from = c.properties.hubspot_owner_id!;
      const other = from === terr ? (terr === "201" ? "202" : "201") : from;
      if (from === terr) { log("contact", c.id, "hubspot_owner_id", from, other, Date.UTC(2025, 10, 3), "204"); }
      log("contact", c.id, "hubspot_owner_id", other, terr, t + 6 * DAY, "204");
      c.properties.hubspot_owner_id = terr;
    }
  });

  // deals and their stage history
  const deals: Obj[] = [];
  let did = 50100;
  const suffix = ["Platform", "Expansion", "New logo", "Analytics add-on", "Renewal", "Multi-year", "Pilot", "Rollout"];
  for (let i = 0; i < 640; i++) {
    const co = pick(live);
    const pipeline = rand() < 0.05 ? "9900001" : rand() < 0.4 ? "8812345" : "default";
    const created = START + between(0, 640) * DAY;
    const close = created + between(35, 140) * DAY;
    const arr = between(15, 180) * 1000;
    const services = rand() < 0.7 ? between(2, 30) * 1000 : 0;
    const owner = COUNTRIES[co.properties.country!]!;
    const id = String(++did);
    const p: Record<string, string> = { dealname: `${co.properties.name!.split(" ")[0]} – ${pick(suffix)}`, pipeline, amount: String(arr + services), arr: String(arr),
      closedate: iso(close), hubspot_owner_id: owner, company_id: co.id, createdate: iso(created), booked: "false",
      partner_tier: rand() < 0.3 ? pick(["gold", "silver"]) : "" };
    // walk the open path, then win/lose (or stay open if the close date is in the future)
    const path = OPEN_PATH[pipeline]!;
    const contractAt = close - between(3, 25) * DAY;
    let stage = path[0]!;
    log("deal", id, "dealstage", null, stage, created, owner);
    const steps = path.length - 1;
    for (let k = 1; k < path.length; k++) {
      const t = k === steps ? contractAt : created + Math.floor(((contractAt - created) * k) / steps);
      if (t > NOW) break;
      log("deal", id, "dealstage", stage, path[k]!, t, owner);
      stage = path[k]!;
    }
    if (close <= NOW) {
      const won = rand() < 0.66;
      if (won) {
        log("deal", id, "dealstage", stage, WON_OF[pipeline]!, close, owner);
        stage = WON_OF[pipeline]!;
        if (rand() < 0.95) {
          const bt = close + between(3, 10) * DAY;
          if (bt <= NOW) { log("deal", id, "booked", "false", "true", bt, "204"); p.booked = "true"; }
        }
      } else if (CONTRACT.has(stage) || rand() < 0.5) {
        log("deal", id, "dealstage", stage, LOST_OF[pipeline]!, close, owner);
        stage = LOST_OF[pipeline]!;
      }
    }
    p.dealstage = stage;
    deals.push({ id, properties: p });
  }

  // monthly forecast snapshots: what RevOps reported as the current quarter's commit at each month end
  const snapshots: Snapshot[] = [];
  for (let y = 2025, m = 0; Date.UTC(y, m + 1, 1) - 1 <= NOW; m === 11 ? (y++, (m = 0)) : m++) {
    const asOf = Date.UTC(y, m + 1, 1) - 1;
    const q = quarterOf(asOf);
    const ids: string[] = [];
    let total = 0;
    for (const d of deals) {
      if (d.properties.pipeline === "9900001") continue;
      const cl = Date.parse(d.properties.closedate!);
      if (cl < q.start || cl > q.end) continue;
      const st = stateAt(history, "deal", d.id, asOf);
      const contractCounts = asOf < Date.parse(TRUTH.drift.from);
      if ((WON.has(st.dealstage ?? "") && st.booked === "true") || (contractCounts && CONTRACT.has(st.dealstage ?? ""))) {
        ids.push(d.id);
        total += Number(d.properties.arr);
      }
    }
    snapshots.push({ as_of: iso(asOf), quarter: q.label, reported_commit_usd: total, deal_ids: ids });
  }

  history.sort((a, b) => a.changed_at.localeCompare(b.changed_at));
  return { deals, contacts, companies, history, snapshots };
}

/** Reconstruct an object's properties as of a time from its field history. */
export function stateAt(history: Change[], object: Change["object"], id: string, t: number): Record<string, string> {
  const out: Record<string, string> = {};
  for (const h of history) {
    if (h.object !== object || h.id !== id) continue;
    if (Date.parse(h.changed_at) > t) continue;
    if (h.new == null) delete out[h.property];
    else out[h.property] = h.new;
  }
  return out;
}

export const isWonStage = (s: string) => WON.has(s);
export const isContractStage = (s: string) => CONTRACT.has(s);
export const isLostStage = (s: string) => LOST.has(s);

// ── REST API (HubSpot-style CRM + read-only warehouse) ───────────────────────

type ObjType = "deals" | "contacts" | "companies";
const singular: Record<ObjType, Change["object"]> = { deals: "deal", contacts: "contact", companies: "company" };

/** All of GurtAI's simulated systems behind one host: the CRM + warehouse, the ERP (/erp) and the support inbox (/mail). */
export class GurtaiSystem {
  readonly world: World;
  readonly erp: ErpSystem;
  readonly mail: MailSystem;
  constructor(readonly token: string, seed?: number) {
    this.world = generate(seed);
    this.erp = new ErpSystem();
    this.mail = new MailSystem();
  }

  private table(t: string): Obj[] | null {
    return t === "deals" ? this.world.deals : t === "contacts" ? this.world.contacts : t === "companies" ? this.world.companies : null;
  }

  handle(req: Req): Res {
    if (req.path === "/health") return { status: 200, body: { ok: true, system: "gurtai-crm" } };
    if (req.auth !== `Bearer ${this.token}`) return { status: 401, body: { status: "error", category: "INVALID_AUTHENTICATION", message: "Authentication credentials not found." } };
    const p = req.path.replace(/\/+$/, "");
    if (p.startsWith("/erp/")) return this.erp.handle(req.method, p, req.query);
    if (p.startsWith("/mail/")) return this.mail.handle(req.method, p, req.query);
    let m: RegExpMatchArray | null;

    if (req.method === "GET" && p === "/crm/v3/owners") return { status: 200, body: { results: OWNERS.map((o) => ({ ...o, teams: [{ name: o.team }] })) } };
    if (req.method === "GET" && p === "/crm/v3/pipelines/deals") return { status: 200, body: { results: PIPELINES.map((pl) => ({ id: pl.id, label: pl.label, stages: pl.stages.map(([id, label, prob]) => ({ id, label, metadata: { probability: String(prob) } })) })) } };
    if (req.method === "GET" && (m = p.match(/^\/crm\/v3\/properties\/(deals|contacts|companies)$/))) return { status: 200, body: { results: PROPERTIES[m[1]!] } };

    if ((m = p.match(/^\/crm\/v3\/objects\/(deals|contacts|companies)(?:\/([^/]+))?(?:\/(search))?$/))) {
      const type = m[1] as ObjType;
      const rows = this.table(type)!;
      if (req.method === "GET" && !m[2]) return { status: 200, body: this.page(rows, Number(req.query.limit ?? 10), req.query.after, req.query.properties) };
      if (req.method === "GET" && m[2]) {
        const o = rows.find((x) => x.id === m![2]);
        return o ? { status: 200, body: this.view(o, req.query.properties) } : { status: 404, body: { status: "error", category: "OBJECT_NOT_FOUND", message: "Object not found." } };
      }
      if (req.method === "POST" && m[2] === "search") {
        const b = (req.body ?? {}) as { filterGroups?: { filters: Filter[] }[]; properties?: string[]; limit?: number; after?: string };
        const limit = b.limit ?? 10;
        if (limit < 1 || limit > 200) return { status: 400, body: { status: "error", category: "VALIDATION_ERROR", message: "limit must be between 1 and 200" } };
        for (const g of b.filterGroups ?? []) for (const f of g.filters) {
          if (["closedate", "createdate"].includes(f.propertyName) && f.value !== undefined && !/^\d{10,14}$/.test(String(f.value))) {
            return { status: 400, body: { status: "error", category: "VALIDATION_ERROR", message: `Date filters on ${f.propertyName} need epoch milliseconds.` } };
          }
        }
        const hits = rows.filter((o) => !b.filterGroups?.length || b.filterGroups.some((g) => g.filters.every((f) => match(o.properties, f))));
        return { status: 200, body: { total: hits.length, ...this.page(hits, limit, b.after, b.properties?.join(",")) } };
      }
    }

    if (req.method === "GET" && p === "/warehouse/field_history") {
      const q = req.query;
      let rows = this.world.history;
      if (q.object) rows = rows.filter((h) => h.object === q.object);
      if (q.property) rows = rows.filter((h) => h.property === q.property);
      if (q.id) rows = rows.filter((h) => h.id === q.id);
      if (q.since) rows = rows.filter((h) => h.changed_at >= q.since!);
      if (q.until) rows = rows.filter((h) => h.changed_at <= q.until!);
      const limit = Math.min(Number(q.limit ?? 1000), 5000);
      const off = Number(q.after ?? 0);
      const page = rows.slice(off, off + limit);
      return { status: 200, body: { total: rows.length, results: page, ...(off + page.length < rows.length ? { paging: { next: { after: String(off + page.length) } } } : {}) } };
    }
    if (req.method === "GET" && p === "/warehouse/forecast_snapshots") return { status: 200, body: { results: this.world.snapshots } };
    if (req.method === "GET" && p === "/warehouse/tables") {
      return { status: 200, body: { tables: [
        { name: "field_history", columns: ["object", "id", "property", "old", "new", "changed_at", "changed_by"], description: "Every property change in the CRM" },
        { name: "forecast_snapshots", columns: ["as_of", "quarter", "reported_commit_usd", "deal_ids"], description: "Commit reported by RevOps at each month end" },
      ] } };
    }
    return { status: 404, body: { status: "error", category: "NOT_FOUND", message: `No route ${req.method} ${p}` } };
  }

  private view(o: Obj, props?: string) {
    const names = props ? props.split(",").filter(Boolean) : Object.keys(o.properties);
    return { id: o.id, properties: Object.fromEntries(names.map((n) => [n, o.properties[n] ?? null])) };
  }

  private page(rows: Obj[], limit: number, after?: string, props?: string) {
    const off = Number(after ?? 0);
    const lim = Math.max(1, Math.min(limit, 200));
    const page = rows.slice(off, off + lim);
    return { results: page.map((o) => this.view(o, props)), ...(off + page.length < rows.length ? { paging: { next: { after: String(off + page.length) } } } : {}) };
  }
}

interface Filter { propertyName: string; operator: string; value?: string | number; highValue?: string | number; values?: (string | number)[] }
function match(props: Record<string, string>, f: Filter): boolean {
  const raw = props[f.propertyName];
  const isDate = ["closedate", "createdate"].includes(f.propertyName);
  const num = (v: unknown) => isDate ? (/^\d+$/.test(String(v)) ? Number(v) : Date.parse(String(v))) : Number(v);
  switch (f.operator) {
    case "EQ": return raw !== undefined && String(raw).toLowerCase() === String(f.value).toLowerCase();
    case "NEQ": return raw === undefined || String(raw).toLowerCase() !== String(f.value).toLowerCase();
    case "IN": return raw !== undefined && (f.values ?? []).map((v) => String(v).toLowerCase()).includes(String(raw).toLowerCase());
    case "HAS_PROPERTY": return raw !== undefined && raw !== "";
    case "NOT_HAS_PROPERTY": return raw === undefined || raw === "";
    case "GT": return raw !== undefined && num(raw) > num(f.value);
    case "GTE": return raw !== undefined && num(raw) >= num(f.value);
    case "LT": return raw !== undefined && num(raw) < num(f.value);
    case "LTE": return raw !== undefined && num(raw) <= num(f.value);
    case "BETWEEN": return raw !== undefined && num(raw) >= num(f.value) && num(raw) <= num(f.highValue);
    default: return false;
  }
}
export const singularOf = singular;
